A_fifo.verilog:
module fifo (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    output reg [2:0] count
);
    reg [1:0] wptr, rptr;
    initial begin wptr = 0; rptr = 0; count = 0; end

    wire do_push = push && count != 3'd4;
    wire do_pop  = pop  && count != 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 0; rptr <= 0; count <= 0;
        end else begin
            if (do_push) wptr <= wptr + 1;
            if (do_pop)  rptr <= rptr + 1;
            case ({do_push, do_pop})
                2'b10:   count <= count + 1;
                2'b01:   count <= count - 1;
                default: count <= count;
            endcase
        end
    end

    always @(posedge clk)
        if (count == 3'd0)
            assert (wptr == rptr);
endmodule

B_onehot.verilog:
module onehot_fsm (
    input wire clk,
    input wire rst,
    input wire step,
    output reg [3:0] state
);
    initial state = 4'b0001;

    always @(posedge clk) begin
        if (rst)
            state <= 4'b0001;
        else if (step)
            state <= {state[2:0], state[3]};
    end

    always @(posedge clk)
        assert (!(state[0] && state[2]));
endmodule

C_kitest.verilog:
module kitest (
    input wire i_clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_in,
    output wire o_bit
);
    parameter LN = 32;
    reg [LN-1:0] sa, sb;
    initial sa = 0;
    initial sb = 0;

    always @(posedge i_clk)
        if (i_reset) begin
            sa <= 0;
            sb <= 0;
        end else if (i_ce) begin
            sa <= { sa[LN-2:0], i_in };
            sb <= { sb[LN-2:0], i_in };
        end

    assign o_bit = sa[LN-1] ^ sb[LN-1];

    always @(*)
        assert (!o_bit);
endmodule
